export const title = "How to Check a Three-Device Charger for Your Phone, Watch, and Earbuds";
export const metaTitle = "3-in-1 Chargers for Phone, Watch and Earbuds";
export const metaDescription = "Verify each charging zone separately, including watch model, earbuds case, phone case, power supply, clearance, and daily removal.";
